from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
import itertools

n = 17
# partition into 4 parts: sizes 5,4,4,4
parts = [list(range(0,5)), list(range(5,9)), list(range(9,13)), list(range(13,17))]
part_of = {}
for i, p in enumerate(parts):
    for v in p:
        part_of[v] = i

# map allowed edges to SAT variables (1-based)
edge_var = {}
var_counter = 1
for u in range(n):
    for v in range(u+1, n):
        if part_of[u] != part_of[v]:
            edge_var[(u,v)] = var_counter
            var_counter += 1

num_edge_vars = var_counter - 1
print(f"Number of possible edges: {num_edge_vars}")

solver = Glucose3()

def add_cycle_forbid(verts):
    k = len(verts)
    clause = []
    for i in range(k):
        a = verts[i]
        b = verts[(i+1)%k]
        if a > b:
            a, b = b, a
        if (a,b) not in edge_var:
            return
        clause.append(-edge_var[(a,b)])
    solver.add_clause(clause)

# Forbid cycles of length 3-6
cycle_counts = {3:0, 4:0, 5:0, 6:0}
for size in [3,4,5,6]:
    for subset in itertools.combinations(range(n), size):
        a = subset[0]  # min element because subset is sorted
        rest = list(subset[1:])
        for perm in itertools.permutations(rest):
            if list(perm) < list(perm[::-1]):
                cycle = (a,) + perm
                add_cycle_forbid(cycle)
                cycle_counts[size] += 1

print("Cycle clauses added:", cycle_counts)

# Cardinality constraint: at least 30 edges
edge_lits = list(edge_var.values())
card_clauses, card_vars = CardEnc.atleast(lits=edge_lits, bound=30, encoding=EncType.totalizer)
for clause in card_clauses:
    solver.add_clause(clause)

print("Added cardinality constraint >= 30")
print("Total variables:", solver.nvars())

# Solve
print("Solving...")
sat = solver.solve()
print("SAT:", sat)

if sat:
    model = solver.get_model()
    # extract true edges
    edges = []
    for (u,v), var in edge_var.items():
        if var in model:
            edges.append((u,v))
    print(f"Number of edges: {len(edges)}")
    print("Edges:", edges)
else:
    print("UNSAT")

