import random

def try_greedy(seed, max_attempts=10000):
    random.seed(seed)
    n = 17
    # 4-coloring partition
    colors = [i % 4 for i in range(n)]

    # adjacency matrix
    adj = [[False]*n for _ in range(n)]
    edges = []

    # all possible edges (between different colors)
    possible = []
    for u in range(n):
        for v in range(u+1, n):
            if colors[u] != colors[v]:
                possible.append((u,v))

    random.shuffle(possible)

    def has_short_cycle(u, v):
        # check if adding edge (u,v) creates cycle of length 3-6
        # BFS from u, avoiding direct edge to v
        for target, avoid in [(u, v), (v, u)]:
            # BFS up to distance 5
            dist = [-1]*n
            parent = [-1]*n
            dist[target] = 0
            queue = [target]
            for x in queue:
                if dist[x] >= 5:
                    continue
                for y in range(n):
                    if not adj[x][y]:
                        continue
                    if y == avoid and x == target:
                        continue
                    if dist[y] == -1:
                        dist[y] = dist[x] + 1
                        parent[y] = x
                        queue.append(y)
            # if we can reach avoid from target in distance <= 5, adding edge creates short cycle
            if dist[avoid] != -1 and dist[avoid] <= 5:
                return True
        return False

    for u, v in possible:
        if not has_short_cycle(u, v):
            adj[u][v] = adj[v][u] = True
            edges.append((u,v))

    return edges

best = []
for seed in range(1000):
    edges = try_greedy(seed)
    if len(edges) > len(best):
        best = edges
        print(f"Seed {seed}: {len(edges)} edges")
        if len(edges) >= 30:
            break

print(f"Best found: {len(best)} edges")
print(best)
